package org.papiricoh.create_nuclearindustry.data;

import static org.papiricoh.create_nuclearindustry.data.LangEntries.add;

/**
 * Lang for the JEI info pages of the power plant areas (listed in
 * {@link org.papiricoh.create_nuclearindustry.integration.jei.PlantJeiInfo}) and the vitrification category.
 * The numbers quoted are the config defaults.
 */
final class PlantJeiDataGen extends AreaDataGen {
    static final PlantJeiDataGen INSTANCE = new PlantJeiDataGen();
    private static final String INFO = "jei.create_nuclearindustry.info.";

    private PlantJeiDataGen() {}

    @Override
    void lang() {
        vitrification();
        pressurizedWaterReactor();
        spentFuel();
        waste();
        controlRoom();
        civilDefense();
    }

    private static void vitrification() {
        add("jei.create_nuclearindustry.category.vitrification", "Vitrification", "Vitrificación");
        String v = "jei.create_nuclearindustry.vitrification.";
        add(v + "time", "%s s", "%s s");
        add(v + "time_superheated", "%s s (%s s superheated)", "%s s (%s s sobrecalentado)");
        add(v + "cake_faster", "Optional: a superheated Blaze Burner melts twice as fast",
                "Opcional: un quemador de blaze sobrecalentado funde el doble de rápido");
        add(v + "cake_required", "Needs a superheated Blaze Burner", "Necesita un quemador de blaze sobrecalentado");
    }

    private static void pressurizedWaterReactor() {
        add(INFO + "pressurizer",
                "Turns a fission reactor into a pressurized water reactor. Stack 2 to 4 Pressurizer or Pressurizer Heater Port blocks on the reactor's lid, anywhere but over the controller or a control rod channel, cap them with a Relief Valve and fill the reactor with Primary Coolant (boron mixed into water) instead of water. The coolant then carries the heat out without boiling: Mechanical Pumps must move the Hot Primary Coolant from an output port to a Steam Generator and the cooled coolant back into an input port; with every pump stopped only a trickle circulates. Heater ports hold 155 bar on their own; wrench one for manual mode, where it heats only while powered by redstone. The valve opens at 170 bar and can stick open: a redstone signal on it shuts it off. A comparator reads 15 from it while it is open.",
                "Convierte un reactor de fisión en un reactor de agua a presión. Apila de 2 a 4 bloques de Presionador o de Puerto calefactor del presionador sobre la tapa del reactor, en cualquier sitio menos encima del controlador o de un canal de barras de control, corónalos con una Válvula de alivio y llena el reactor de Refrigerante primario (agua con boro) en lugar de agua. Así el refrigerante saca el calor sin hervir: unas Bombas mecánicas tienen que llevar el Refrigerante primario caliente de un puerto de salida a un Generador de vapor y devolver el ya enfriado a un puerto de entrada; con todas las bombas paradas solo circula un hilo. Los puertos calefactores mantienen solos 155 bar; con la llave pasan a modo manual y solo calientan mientras reciben redstone. La válvula abre a 170 bar y puede quedarse abierta: una señal de redstone sobre ella la cierra. Un comparador lee 15 mientras está abierta.");
        add(INFO + "steam_generator",
                "Boils feedwater with the heat of a pressurized reactor's primary coolant. A 3x3 column 4 to 8 blocks tall: full layers of casing on top and bottom, and in the layers between, a column of Tube Bundles in the middle walled in by Casing, Ports and the Controller, which faces out with a tube bundle right behind it. Wrench each Port to set what it carries: Primary in (hot coolant from the reactor), Primary out (cooled coolant back to the reactor), Feedwater in (water) and Steam out (to the turbines); it needs one of each. More tube bundles move more heat. If the feedwater runs out the tubes dry up and stop cooling the reactor.",
                "Hierve agua de alimentación con el calor del refrigerante primario de un reactor a presión. Una columna de 3x3 y de 4 a 8 bloques de alto: capas completas de carcasa arriba y abajo y, en las capas de en medio, una columna de Haces de tubos en el centro rodeada de Carcasa, Puertos y el Controlador, que mira hacia fuera con un haz de tubos justo detrás. Con la llave eliges qué lleva cada Puerto: Entrada del primario (refrigerante caliente del reactor), Salida del primario (refrigerante enfriado de vuelta al reactor), Entrada de agua de alimentación (agua) y Salida de vapor (hacia las turbinas); necesita uno de cada. Cuantos más haces de tubos, más calor pasa. Si se acaba el agua de alimentación los tubos se secan y dejan de enfriar el reactor.");
        add(INFO + "containment",
                "Build a sealed building around the reactor and place a Containment Monitor anywhere inside: it measures the air enclosed (up to 32768 blocks) and keeps the steam, hydrogen and radioactivity of an accident in instead of letting them out. Gas leaks through anything that is not a full block, such as doors, slabs and pipes. Every wall block holds a pressure: Containment Concrete 6 bar, Steel Liner 8, ordinary blocks 1.5; above the weakest one the building bursts there. Pipes go through Containment Penetrations, which pass fluid along their axis. Passive Autocatalytic Recombiners set in the wall remove hydrogen before it burns (4% can ignite, 8% always does); a Filtered Vent in the wall opens with redstone and bleeds the overpressure out, keeping 99% of the radioactivity. Click the monitor to measure again or to clear a repaired burst; comparators read the pressure against what the weakest wall holds.",
                "Levanta un edificio estanco alrededor del reactor y pon un Monitor de contención en cualquier parte dentro: mide el aire encerrado (hasta 32768 bloques) y retiene el vapor, el hidrógeno y la radiactividad de un accidente en vez de soltarlos. El gas se escapa por todo lo que no sea un bloque completo, como puertas, losas y tuberías. Cada bloque de la pared aguanta una presión: el Hormigón de contención 6 bar, el Revestimiento de acero 8 y los bloques normales 1,5; si se supera la del más débil, el edificio revienta por ahí. Las tuberías cruzan por Penetraciones de contención, que pasan fluido a lo largo de su eje. Los Recombinadores autocatalíticos pasivos puestos en la pared eliminan el hidrógeno antes de que arda (con un 4% puede prender y con un 8% prende siempre); un Venteo filtrado en la pared se abre con redstone y deja salir la sobrepresión reteniendo el 99% de la radiactividad. Haz clic en el monitor para volver a medir o para dar por reparada una rotura; los comparadores leen la presión frente a lo que aguanta la pared más débil.");
        add(INFO + "containment_door",
                "A two-block-high steel door for the containment wall. Shut, it seals like the wall around it and holds 8 bar; open, the doorway is a hole in the containment. Click it or power it with redstone: it pulls out of its frame and slides sideways along the wall. Two side by side, hinged on opposite sides, open as a pair. While the containment behind it is more than 0.2 bar above the outside it stays pressure-locked and will not open.",
                "Una puerta de acero de dos bloques de alto para la pared de la contención. Cerrada, sella como la pared que la rodea y aguanta 8 bar; abierta, el hueco es un agujero en la contención. Haz clic en ella o dale una señal de redstone: sale de su marco y se desliza hacia un lado, pegada a la pared. Dos juntas, con las bisagras en lados opuestos, se abren a la vez. Mientras la contención tras ella esté a más de 0,2 bar por encima del exterior, queda bloqueada por presión y no se abre.");
        add(INFO + "corium",
                "When an overheated core melts, its fuel turns into Corium: molten core that falls through open space and melts its way down through blocks until its heat runs out, then freezes into Solidified Corium, which stays fiercely radioactive and slowly contaminates its chunk. Corium meeting water sets off a steam explosion, and melting concrete inside a containment gives off more hydrogen. It cannot melt bedrock or very blast-resistant blocks, and on a Core Catcher floor under the reactor it spreads out and freezes fast. Before that, cladding hotter than 1200 °C reacts with steam and makes hydrogen, and a pressurized vessel kept above 250 bar breaks. Setting pwr.accidents.legacyMeltdown in the config brings back the old meltdown: one big explosion and wide fallout.",
                "Cuando un núcleo sobrecalentado se funde, su combustible se convierte en Corium: núcleo fundido que cae por el espacio libre y se abre paso fundiendo los bloques de debajo hasta que se le acaba el calor; entonces se solidifica en Corium solidificado, que sigue siendo muy radiactivo y contamina poco a poco su chunk. Si el corium toca agua provoca una explosión de vapor, y al fundir hormigón dentro de una contención suelta más hidrógeno. No puede fundir la roca madre ni los bloques muy resistentes a explosiones, y sobre un suelo de Recogedor del núcleo bajo el reactor se extiende y se solidifica enseguida. Antes de eso, las vainas a más de 1200 °C reaccionan con el vapor y producen hidrógeno, y una vasija a presión que pasa demasiado tiempo por encima de 250 bar se rompe. Activar pwr.accidents.legacyMeltdown en la configuración recupera la fusión antigua: una gran explosión y lluvia radiactiva en un área amplia.");
    }

    private static void spentFuel() {
        add(INFO + "spent_fuel",
                "Spent fuel leaves the core Hot and cools as its short-lived fission products decay: Hot for about two in-game days, then Warm, Cooled after about a week and Aged after about three weeks. The tooltip shows the grade. Hot fuel is the most radioactive and burns bare hands; cooler fuel crushes into more fragments and less waste, so each grade has its own crushing recipe. Put fresh assemblies in Spent Fuel Racks at the bottom of a water pool: every block of water straight above a rack cuts its radiation, and two or more make it safe. The pool must also carry the decay heat away (0.4 kW per water block, up to 20 kW per fresh assembly) or it boils off a layer at a time; Pool Coolers in the water, turned by a shaft from above, add up to 60 kW each at 64 RPM. Fuel that is Warm or cooler can go into a Dry Cask, which lets almost nothing out. Both hold nine assemblies: click with fuel to load, empty-handed to take one out. Hoppers work and comparators read how full they are.",
                "El combustible gastado sale del núcleo Caliente y se enfría a medida que se desintegran sus productos de fisión de vida corta: Caliente unos dos días de juego, luego Templado, Enfriado a la semana más o menos y Envejecido a las tres semanas. La descripción del objeto muestra el grado. El combustible caliente es el más radiactivo y quema las manos desnudas; el más frío se tritura en más fragmentos y menos residuos, así que cada grado tiene su propia receta de trituración. Mete los elementos recién sacados en Bastidores de combustible gastado en el fondo de una piscina: cada bloque de agua justo encima de un bastidor reduce su radiación, y con dos o más ya es seguro. La piscina también tiene que llevarse el calor residual (0,4 kW por bloque de agua, hasta 20 kW por elemento recién sacado) o se evapora capa a capa; los Refrigeradores de piscina sumergidos y movidos por un eje desde arriba añaden hasta 60 kW cada uno a 64 RPM. El combustible Templado o más frío puede ir a un Contenedor de almacenamiento en seco, que casi no deja salir nada. Los dos guardan nueve elementos: haz clic con combustible para cargarlos y con la mano vacía para sacar uno. Funcionan con tolvas y los comparadores leen lo llenos que están.");
    }

    private static void waste() {
        add(INFO + "waste_classes",
                "Radioactive waste comes in three classes, each with its own treatment. Low-Level Waste (from contaminated water and radiation scrubbers) is compacted with an iron sheet by a Mechanical Press over a basin into a Compacted Waste Drum. Intermediate-Level Waste (from crushing spent fuel and spent pellets) is mixed with sand, gravel, water and an iron sheet into a Cemented Waste Drum. High-Level Waste (the fission products from reprocessing) is fierce and warm: melt it with sand and borax in a Vitrification Melter into a Vitrified Waste Canister. Treated packages leak less and store better in a repository.",
                "Los residuos radiactivos son de tres clases, cada una con su tratamiento. Los Residuos de baja actividad (del agua contaminada y de los absorbedores de radiación) se compactan con una lámina de hierro con una Prensa mecánica sobre una cuenca en un Bidón de residuos compactados. Los Residuos de media actividad (de triturar combustible gastado y pastillas agotadas) se mezclan con arena, grava, agua y una lámina de hierro en un Bidón de residuos cementados. Los Residuos de alta actividad (los productos de fisión del reprocesado) son muy activos y calientes: fúndelos con arena y bórax en un Fundidor de vitrificación para obtener un Contenedor de residuos vitrificados. Los bultos tratados se filtran menos y se almacenan mejor en un repositorio.");
        add(INFO + "vitrification_melter",
                "Melts high-level waste with sand and borax into a Vitrified Waste Canister. It has no heater of its own: like a basin, it sits on a Blaze Burner that must be lit, and a superheated burner melts twice as fast. Click it with ingredients or feed it with funnels and hoppers; each kind of ingredient gets its own slot. Click it empty-handed to take the canisters out, or sneak to take an ingredient back. The waste inside irradiates through its walls.",
                "Funde los residuos de alta actividad con arena y bórax en un Contenedor de residuos vitrificados. No tiene calentador propio: como una cuenca, va encima de un quemador de blaze que tiene que estar encendido, y uno sobrecalentado funde el doble de rápido. Haz clic con los ingredientes o aliméntalo con embudos y tolvas; cada tipo de ingrediente va en su propio hueco. Haz clic con la mano vacía para sacar los contenedores, o agachado para recuperar un ingrediente. Los residuos de dentro irradian a través de sus paredes.");
    }

    private static void controlRoom() {
        add(INFO + "chart_recorder",
                "Draws up to three readings of a linked machine on a strip of paper. Link it with a Control Room Linker like a monitor, give it paper by hand or with a hopper, and wrench it to choose what each pen draws and how fast the paper runs (a sample every 1, 5 or 20 ticks). One sheet lasts 240 samples; without paper the chart stops, and a comparator reads how much is left. Click it to see the paper left; sneak-click empty-handed to tear the chart off as a Chart Roll, which you can use anywhere to read it.",
                "Dibuja hasta tres lecturas de una máquina enlazada en una tira de papel. Enlázalo con un Enlazador de sala de control como un monitor, dale papel a mano o con una tolva y usa la llave para elegir qué dibuja cada plumilla y a qué velocidad corre el papel (una muestra cada 1, 5 o 20 ticks). Cada hoja da para 240 muestras; sin papel la gráfica se detiene, y un comparador lee cuánto queda. Haz clic para ver el papel que queda; agachado y con la mano vacía arrancas la gráfica como un Rollo de gráfica, que puedes usar en cualquier sitio para leerla.");
        add(INFO + "annunciator_panel",
                "Six alarm windows over an ACK and a RESET button. Click a window with a Control Room Linker to link it to a reactor, turbine, steam generator, containment or any other machine (click the frame to link all six), and wrench a window to choose its alarm, threshold and label. A tripped window flashes and the horn sounds until you press ACK; it then stays lit while the condition lasts, flashes slowly once it clears and goes dark on RESET. The first window to trip is marked as the first out. Redstone pulses into its left and right sides (seen from the front) press ACK and RESET; the back and bottom give a signal while an alarm waits for ACK, and a comparator reads how many windows are lit.",
                "Seis ventanas de alarma sobre un botón de reconocimiento (RECON.) y otro de rearme. Haz clic en una ventana con un Enlazador de sala de control para enlazarla a un reactor, turbina, generador de vapor, contención o cualquier otra máquina (haz clic en el marco para enlazar las seis), y usa la llave sobre una ventana para elegir su alarma, umbral y etiqueta. Una ventana disparada parpadea y la bocina suena hasta que pulsas RECON.; luego sigue encendida mientras dure la condición, parpadea despacio cuando se despeja y se apaga al rearmar. La primera ventana en dispararse queda marcada como primera alarma. Los pulsos de redstone en sus lados izquierdo y derecho (vistos de frente) pulsan RECON. y REARME; la parte trasera y la de abajo dan señal mientras una alarma espera reconocimiento, y un comparador lee cuántas ventanas están encendidas.");
        add(INFO + "controller_module",
                "A Control Desk module that runs the reactor on its own. Fit it in a desk linked to a fission reactor and wrench it to choose Automatic power (setpoint in MW), Automatic temperature (in °C) or, on a reactor with a pressurizer, Automatic pressure (in bar, through the heaters and the spray), and to switch it between automatic and standby. Click it to raise the setpoint and sneak-click to lower it. In power and temperature mode it sets the reactor's rod target like a PID controller; Redstone Ports in Insert rods or Withdraw rods mode still have to drive the rod pistons. It lets go during a SCRAM or while the core is not formed, and picks up smoothly again afterwards. Tune it under controlRoom.pid in the config.",
                "Un módulo de Pupitre de control que maneja el reactor por sí solo. Colócalo en un pupitre enlazado a un reactor de fisión y usa la llave para elegir Potencia automática (consigna en MW), Temperatura automática (en °C) o, en un reactor con presionador, Presión automática (en bar, con los calentadores y el rociado), y para pasarlo de automático a en espera. Haz clic para subir la consigna y agachado para bajarla. En potencia y temperatura fija el objetivo de barras del reactor como un controlador PID; los Puertos de redstone en modo Insertar barras o Extraer barras siguen teniendo que mover los pistones de las barras. Se suelta durante un SCRAM o si el núcleo no está formado, y después retoma el control sin saltos. Se ajusta en controlRoom.pid en la configuración.");
    }

    private static void civilDefense() {
        add(INFO + "sirens",
                "The Air Raid Siren sounds a steady alert while it gets a redstone signal, and on its own the faster attack warning when a missile, bomb or launch countdown is aimed within 96 blocks of it, plus the reach of the threat's fallout. The Hand-Crank Siren needs no power: it sounds while its shaft from below turns at 32 RPM or more, higher pitched the faster it turns. Both can be heard 128 blocks away, and a comparator reads 15 from them while they sound.",
                "La Sirena antiaérea suena con una alerta continua mientras recibe una señal de redstone, y por sí sola con el aviso de ataque, más rápido, cuando un misil, una bomba o una cuenta atrás de lanzamiento apunta a menos de 96 bloques de ella, más el alcance de la lluvia radiactiva de la amenaza. La Sirena de manivela no necesita energía: suena mientras su eje, desde abajo, gira a 32 RPM o más, y más aguda cuanto más rápido gira. Las dos se oyen a 128 bloques, y un comparador lee 15 mientras suenan.");
        add(INFO + "seismic_detector",
                "Feels every nuclear and dirty bomb detonation in its dimension and remembers the last eight: power, distance, bearing and how long ago. Read it with goggles (sneak to see them all) or a Display Link. A comparator follows the strongest detonation of the last five minutes, weaker the farther away it went off.",
                "Siente todas las detonaciones nucleares y de bombas sucias de su dimensión y recuerda las ocho últimas: potencia, distancia, rumbo y hace cuánto. Léelo con las gafas (agáchate para verlas todas) o con un Display Link. Un comparador sigue la detonación más fuerte de los últimos cinco minutos, más débil cuanto más lejos ocurrió.");
        add(INFO + "blast_door",
                "A sliding door that survives nuclear blasts. Fill a 2x2 to 4x4 opening with Steel or Lead Blast Door leaves and ring it with Blast Door Frame, with a Blast Door Controller as one of the frame blocks; the controller's shaft runs through the wall, across the door. Turning the shaft one way opens the door and the other way shuts it, faster at higher speed; without rotation, a rising redstone signal opens it and a falling one shuts it. The panel slides towards the controller when it sits beside the door. Shut leaves shrug off explosions, count as containment wall and stop radiation: lead lets 2% through, steel 15%. A comparator reads how far open the door is.",
                "Una puerta corredera que aguanta las explosiones nucleares. Llena un hueco de 2x2 a 4x4 con hojas de Puerta blindada de acero o de plomo y rodéalo de Marco de puerta blindada, con un Controlador de puerta blindada como uno de los bloques del marco; el eje del controlador atraviesa la pared, cruzando la puerta. Girar el eje en un sentido abre la puerta y en el otro la cierra, más rápido cuanto más velocidad; sin rotación, una señal de redstone que se enciende la abre y una que se apaga la cierra. La hoja se desliza hacia el controlador cuando este está al lado de la puerta. Cerradas, las hojas resisten las explosiones, cuentan como pared de contención y frenan la radiación: el plomo deja pasar el 2% y el acero el 15%. Un comparador lee cuánto está abierta.");
        add(INFO + "shelter",
                "Place it inside a closed room to make a fallout shelter; its shaft can come in through the wall. It surveys the room: up to 4096 blocks of air, with every block of the walls, floor and ceiling solid and at least as blast resistant as concrete (no glass or wool). A certified shelter lets in only 10% of a blast wave's overpressure, and while the unit turns at 16 RPM or more it filters out 95% of the dose from fallout and contaminated ground. Goggles show what is missing.",
                "Colócala dentro de una sala cerrada para convertirla en un refugio antiatómico; su eje puede entrar atravesando la pared. Inspecciona la sala: hasta 4096 bloques de aire, con todos los bloques de paredes, suelo y techo sólidos y al menos tan resistentes a explosiones como el hormigón (nada de cristal ni lana). Un refugio certificado solo deja entrar el 10% de la sobrepresión de una onda expansiva y, mientras la unidad gira a 16 RPM o más, filtra el 95% de la dosis de la lluvia radiactiva y del suelo contaminado. Las gafas muestran lo que falta.");
    }
}
